def even_basis(M):
    """F^{(+)} = {f | eps f = f} の正規直交基底（列ベクトルを並べた行列）。"""
    E = eps_op(M)
    w, V = np.linalg.eigh(E)                 # eps はエルミート（実対称）
    cols = [V[:,k] for k in range(len(w)) if abs(w[k] - _sage_const_1p0 ) < _sage_const_1en8 ]
    return np.array(cols).T

